65	                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
66	                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
67	              }`}
68	            >
69	              {t}
70	            </button>
71	          );
72	        })}
73	      </div>
74	      <div className="animate-fade-up">{panels[tab]}</div>
75	    </div>
76	  );
77	}
