1	import { NextRequest, NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { vmRrd, nodeRrd } from "@/lib/proxmox";
5	
6	export async function GET(req: NextRequest) {
7	  const user = await currentUser();
8	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
9	
10	  const timeframe = ["hour", "day", "week", "month"].includes(req.nextUrl.searchParams.get("tf") ?? "")
11	    ? req.nextUrl.searchParams.get("tf")!
12	    : "hour";
13	
14	  const serverId = req.nextUrl.searchParams.get("serverId");
15	  try {
16	    if (serverId) {
17	      const server = await db.server.findUnique({ where: { id: serverId } });
18	      if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
19	        return NextResponse.json({ error: "not found" }, { status: 404 });
20	      }
21	      const data = await vmRrd(server.vmid, timeframe);
22	      return NextResponse.json({ data });
23	    }
24	    if (user.role !== "ADMIN") return NextResponse.json({ error: "forbidden" }, { status: 403 });
25	    const data = await nodeRrd(timeframe);
26	    return NextResponse.json({ data });
27	  } catch {
28	    return NextResponse.json({ data: [] });
29	  }
30	}
