import { NextRequest, NextResponse } from "next/server";
import { createHash, randomUUID } from "node:crypto";
import { EncryptJWT } from "jose";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { pve, node as primaryNode } from "@/lib/proxmox";

export const dynamic = "force-dynamic";

/**
 * In-browser VNC console — ticket issuer.
 *
 * GET /api/console/[serverId]
 *
 * Flow:
 *  1. Authenticate the caller (owner or admin).
 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
 *     an ephemeral port on the Proxmox node.
 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
 *     VNC ticket, and the API token needed to authenticate the websocket
 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
 *     unique jti so the relay can enforce single use.
 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
 *     which only the relay (sharing AUTH_SECRET) can decrypt.
 *
 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
 * credentials, and pipes bytes both ways.
 */

// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
// The relay derives the identical key the same way — no extra shared secret.
function consoleKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set");
  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
}

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { node: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  if (!server.vmid) {
    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
  }
  if (server.status !== "RUNNING") {
    return NextResponse.json(
      { error: "server must be running to open the console" },
      { status: 409 }
    );
  }

  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
  // Node row; otherwise fall back to the primary node from the environment.
  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
  const pveNode = server.node?.pveNode ?? primaryNode;
  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";

  if (!pveNode || !tokenId || !tokenSecret) {
    return NextResponse.json({ error: "console not configured" }, { status: 500 });
  }

  // Request a websocket VNC proxy ticket from Proxmox.
  let vnc: { ticket: string; port: string | number };
  try {
    // Use the node-scoped client for non-primary nodes so the ticket is valid
    // for the right host; the primary node uses the shared `pve` client.
    if (server.node) {
      const { pveFor } = await import("@/lib/proxmox");
      const client = pveFor({
        apiUrl: server.node.apiUrl,
        pveNode: server.node.pveNode,
        tokenId: server.node.tokenId,
        tokenSecret: server.node.tokenSecret,
      });
      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
        websocket: 1,
      });
    } else {
      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
        websocket: 1,
      });
    }
  } catch {
    return NextResponse.json(
      { error: "hypervisor did not grant a console ticket — try again shortly" },
      { status: 502 }
    );
  }

  if (!vnc?.ticket || vnc.port === undefined) {
    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
  }

  const ticketId = randomUUID();

  // Encrypt the full connection target. Only the relay can read this.
  const sid = await new EncryptJWT({
    apiBase,
    node: pveNode,
    vmid: server.vmid,
    port: Number(vnc.port),
    vncticket: vnc.ticket,
    tokenId,
    tokenSecret,
  })
    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
    .setJti(ticketId)
    .setIssuedAt()
    .setExpirationTime("60s")
    .encrypt(consoleKey());

  // Public websocket URL of the relay. In production behind HTTPS, set
  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
  const base =
    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;

  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;

  return NextResponse.json({ wsPath, ticketId });
}

#!/usr/bin/env node
/**
 * Nxeon in-browser VNC console — websocket relay.
 *
 * A tiny standalone process that bridges a browser noVNC websocket to a
 * Proxmox `vncwebsocket` endpoint. The browser never receives the Proxmox API
 * token or the raw VNC ticket — those arrive here inside an encrypted JWE
 * (issued by app/api/console/[serverId]/route.ts) which only this relay, which
 * shares AUTH_SECRET with the web app, can decrypt.
 *
 *   browser  ──ws──▶  console-proxy  ──wss──▶  Proxmox /vncwebsocket
 *            (noVNC)   (holds creds)           (VNC RFB stream)
 *
 * DEPENDENCIES: only Node built-ins (http, tls, crypto, url) + `jose` (already
 * a project dependency — used for JWE). The `ws` npm package is NOT required;
 * the WebSocket framing (server-accept handshake, client handshake, frame
 * encode/decode, masking, fragmentation, ping/pong) is implemented below.
 *
 * ENV (read from the same /opt/nxeon/.env as the web app):
 *   AUTH_SECRET          shared secret — must match the web app (required)
 *   CONSOLE_PROXY_PORT   listen port (default 8899)
 *   CONSOLE_PROXY_HOST   listen address (default 0.0.0.0)
 *
 * Run: node scripts/console-proxy.mjs
 */

import http from "node:http";
import tls from "node:tls";
import { createHash, randomBytes } from "node:crypto";
import { jwtDecrypt } from "jose";

const PORT = Number(process.env.CONSOLE_PROXY_PORT ?? 8899);
const HOST = process.env.CONSOLE_PROXY_HOST ?? "0.0.0.0";
const WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

// 256-bit JWE key derived identically to the web app (lib route consoleKey()).
function consoleKey() {
  const secret = process.env.AUTH_SECRET;
  if (!secret) {
    console.error("[console-proxy] FATAL: AUTH_SECRET not set");
    process.exit(1);
  }
  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
}
const KEY = consoleKey();

// Single-use ticket tracking: jti -> expiry(ms). A ticket may be redeemed once.
const usedJti = new Map();
setInterval(() => {
  const now = Date.now();
  for (const [jti, exp] of usedJti) if (exp < now) usedJti.delete(jti);
}, 30_000).unref();

/* ------------------------------------------------------------------ *
 *  Minimal WebSocket framing over a raw duplex socket.
 *  `maskOut`: true when we act as a WS *client* (browser→Proxmox side must
 *  mask per RFC 6455); false when we act as a WS *server* (frames to the
 *  browser must NOT be masked).
 * ------------------------------------------------------------------ */
class WsConn {
  constructor(socket, maskOut, name) {
    this.socket = socket;
    this.maskOut = maskOut;
    this.name = name;
    this.buf = Buffer.alloc(0);
    this.fragOpcode = 0;
    this.fragChunks = [];
    this.onmessage = null; // (opcode, payload:Buffer) => void
    this.onclose = null;
    this.closed = false;

    socket.on("data", (chunk) => {
      this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : chunk;
      try {
        this._parse();
      } catch (err) {
        console.error(`[console-proxy] frame parse error on ${name}:`, err.message);
        this.close();
      }
    });
    socket.on("close", () => this._fireClose());
    socket.on("error", () => this._fireClose());
  }

  _fireClose() {
    if (this.closed) return;
    this.closed = true;
    if (this.onclose) this.onclose();
  }

  _parse() {
    for (;;) {
      const b = this.buf;
      if (b.length < 2) return;
      const b0 = b[0];
      const b1 = b[1];
      const fin = (b0 & 0x80) !== 0;
      const opcode = b0 & 0x0f;
      const masked = (b1 & 0x80) !== 0;
      let len = b1 & 0x7f;
      let offset = 2;
      if (len === 126) {
        if (b.length < 4) return;
        len = b.readUInt16BE(2);
        offset = 4;
      } else if (len === 127) {
        if (b.length < 10) return;
        len = Number(b.readBigUInt64BE(2));
        offset = 10;
      }
      let maskKey;
      if (masked) {
        if (b.length < offset + 4) return;
        maskKey = b.subarray(offset, offset + 4);
        offset += 4;
      }
      const total = offset + len;
      if (b.length < total) return;
      let payload = Buffer.from(b.subarray(offset, total)); // copy — buf gets sliced
      if (masked) {
        for (let i = 0; i < payload.length; i++) payload[i] ^= maskKey[i & 3];
      }
      this.buf = b.subarray(total);
      this._handleFrame(fin, opcode, payload);
    }
  }

  _handleFrame(fin, opcode, payload) {
    if (opcode === 0x8) {
      // close
      this.close();
      return;
    }
    if (opcode === 0x9) {
      // ping -> reply pong on same socket, and swallow
      this._send(0xa, payload);
      return;
    }
    if (opcode === 0xa) return; // pong -> ignore

    // data (0x1 text, 0x2 binary) or continuation (0x0)
    if (opcode === 0x0) {
      this.fragChunks.push(payload);
      if (fin) {
        const full = Buffer.concat(this.fragChunks);
        const op = this.fragOpcode || 0x2;
        this.fragChunks = [];
        this.fragOpcode = 0;
        if (this.onmessage) this.onmessage(op, full);
      }
      return;
    }
    if (fin) {
      if (this.onmessage) this.onmessage(opcode, payload);
    } else {
      this.fragOpcode = opcode;
      this.fragChunks = [payload];
    }
  }

  /** Encode + write a single (unfragmented) frame. */
  _send(opcode, payload) {
    if (this.closed || this.socket.destroyed) return;
    const len = payload.length;
    let header;
    if (len < 126) {
      header = Buffer.alloc(2);
      header[1] = len;
    } else if (len < 65536) {
      header = Buffer.alloc(4);
      header[1] = 126;
      header.writeUInt16BE(len, 2);
    } else {
      header = Buffer.alloc(10);
      header[1] = 127;
      header.writeBigUInt64BE(BigInt(len), 2);
    }
    header[0] = 0x80 | opcode; // FIN + opcode

    if (this.maskOut) {
      header[1] |= 0x80;
      const mask = randomBytes(4);
      const masked = Buffer.allocUnsafe(len);
      for (let i = 0; i < len; i++) masked[i] = payload[i] ^ mask[i & 3];
      this.socket.write(Buffer.concat([header, mask, masked]));
    } else {
      this.socket.write(Buffer.concat([header, payload]));
    }
  }

  /** Public: forward an application message (preserves text/binary opcode). */
  send(opcode, payload) {
    this._send(opcode === 0x1 ? 0x1 : 0x2, payload);
  }

  close() {
    if (this.closed) {
      try {
        this.socket.destroy();
      } catch {}
      return;
    }
    try {
      this._send(0x8, Buffer.alloc(0));
    } catch {}
    try {
      this.socket.end();
    } catch {}
    this._fireClose();
  }
}

/* ------------------------------------------------------------------ *
 *  Open a WebSocket client connection to Proxmox's vncwebsocket endpoint
 *  over TLS. Resolves with a connected WsConn (client role, masks output).
 * ------------------------------------------------------------------ */
function connectProxmox(target) {
  return new Promise((resolve, reject) => {
    const u = new URL(target.apiBase);
    const host = u.hostname;
    const port = Number(u.port || 8006);

    const path =
      `/api2/json/nodes/${encodeURIComponent(target.node)}` +
      `/qemu/${target.vmid}/vncwebsocket` +
      `?port=${encodeURIComponent(String(target.port))}` +
      `&vncticket=${encodeURIComponent(target.vncticket)}`;

    const key = randomBytes(16).toString("base64");
    const auth = `PVEAPIToken=${target.tokenId}=${target.tokenSecret}`;

    const socket = tls.connect(
      { host, port, servername: host, rejectUnauthorized: false },
      () => {
        const reqLines = [
          `GET ${path} HTTP/1.1`,
          `Host: ${host}:${port}`,
          "Upgrade: websocket",
          "Connection: Upgrade",
          "Sec-WebSocket-Version: 13",
          `Sec-WebSocket-Key: ${key}`,
          "Sec-WebSocket-Protocol: binary",
          `Authorization: ${auth}`,
          `Cookie: PVEAuthCookie=`,
          "",
          "",
        ];
        socket.write(reqLines.join("\r\n"));
      }
    );

    let handshakeBuf = Buffer.alloc(0);
    const onHandshakeData = (chunk) => {
      handshakeBuf = Buffer.concat([handshakeBuf, chunk]);
      const idx = handshakeBuf.indexOf("\r\n\r\n");
      if (idx === -1) {
        if (handshakeBuf.length > 16384) {
          socket.destroy();
          reject(new Error("Proxmox handshake too large"));
        }
        return;
      }
      const head = handshakeBuf.subarray(0, idx).toString("latin1");
      const rest = handshakeBuf.subarray(idx + 4);
      socket.removeListener("data", onHandshakeData);

      const statusLine = head.split("\r\n")[0] || "";
      if (!/ 101 /.test(statusLine)) {
        socket.destroy();
        reject(new Error(`Proxmox refused websocket: ${statusLine.trim()}`));
        return;
      }
      const conn = new WsConn(socket, /* maskOut */ true, "proxmox");
      // Any bytes already buffered after the headers belong to the ws stream.
      if (rest.length) socket.emit("data", rest);
      resolve(conn);
    };
    socket.on("data", onHandshakeData);
    socket.on("error", (err) => reject(err));
    socket.setTimeout(15_000, () => {
      socket.destroy();
      reject(new Error("Proxmox connection timed out"));
    });
    socket.on("secureConnect", () => socket.setTimeout(0));
  });
}

/* ------------------------------------------------------------------ *
 *  HTTP server: accepts the browser websocket upgrade on /console.
 * ------------------------------------------------------------------ */
const server = http.createServer((_req, res) => {
  // Plain health check for the systemd unit / nginx.
  res.writeHead(200, { "Content-Type": "text/plain" });
  res.end("nxeon console-proxy ok\n");
});

server.on("upgrade", async (req, socket) => {
  const url = new URL(req.url, "http://localhost");
  if (url.pathname !== "/console") {
    socket.destroy();
    return;
  }

  const sid = url.searchParams.get("sid");
  const wsKey = req.headers["sec-websocket-key"];
  if (!sid || !wsKey) {
    socket.write("HTTP/1.1 400 Bad Request\r\n\r\n");
    socket.destroy();
    return;
  }

  // Decrypt + validate the ticket (auth, expiry, single use).
  let target;
  try {
    const { payload } = await jwtDecrypt(sid, KEY, { clockTolerance: 5 });
    const jti = payload.jti;
    if (!jti || usedJti.has(jti)) throw new Error("ticket already used");
    // exp is in seconds; keep for cleanup slightly beyond.
    usedJti.set(jti, (payload.exp ?? Math.floor(Date.now() / 1000) + 60) * 1000 + 60_000);
    target = payload;
  } catch (err) {
    console.warn("[console-proxy] rejected ticket:", err.message);
    socket.write("HTTP/1.1 401 Unauthorized\r\n\r\n");
    socket.destroy();
    return;
  }

  // Complete the browser-side WebSocket handshake.
  const accept = createHash("sha1")
    .update(wsKey + WS_GUID)
    .digest("base64");
  const respHeaders = [
    "HTTP/1.1 101 Switching Protocols",
    "Upgrade: websocket",
    "Connection: Upgrade",
    `Sec-WebSocket-Accept: ${accept}`,
  ];
  // noVNC always requests the "binary" subprotocol — echo it back.
  const wantProto = String(req.headers["sec-websocket-protocol"] || "");
  if (wantProto.split(",").map((s) => s.trim()).includes("binary")) {
    respHeaders.push("Sec-WebSocket-Protocol: binary");
  }
  respHeaders.push("", "");
  socket.write(respHeaders.join("\r\n"));

  const browser = new WsConn(socket, /* maskOut */ false, "browser");

  // Connect to Proxmox, then pipe both directions.
  let pve;
  try {
    pve = await connectProxmox(target);
  } catch (err) {
    console.error("[console-proxy] Proxmox connect failed:", err.message);
    browser.close();
    return;
  }

  console.log(`[console-proxy] session open: vmid=${target.vmid} node=${target.node}`);

  browser.onmessage = (op, data) => pve.send(op, data);
  pve.onmessage = (op, data) => browser.send(op, data);
  browser.onclose = () => {
    pve.close();
    console.log(`[console-proxy] session closed (browser): vmid=${target.vmid}`);
  };
  pve.onclose = () => {
    browser.close();
    console.log(`[console-proxy] session closed (proxmox): vmid=${target.vmid}`);
  };
});

server.on("clientError", (_err, socket) => {
  try {
    socket.destroy();
  } catch {}
});

server.listen(PORT, HOST, () => {
  console.log(`[console-proxy] listening on ws://${HOST}:${PORT}/console`);
});

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * In-browser VNC console.
 *
 * Fetches a single-use, encrypted ticket from /api/console/[serverId], then
 * connects the browser to the standalone relay websocket (scripts/console-proxy.mjs)
 * using the vendored noVNC RFB client (public/novnc/core/rfb.js).
 *
 * The Proxmox token and raw VNC ticket are NEVER seen here — the ticket handed
 * to us is an opaque encrypted blob that only the relay can decrypt.
 */

type Phase = "idle" | "loading" | "connecting" | "connected" | "error" | "unavailable";

// Hide the import from the bundler so it stays a genuine runtime browser import
// of the static ESM asset under /public/novnc — Turbopack/Webpack must not try
// to resolve or bundle it.
const importESM: (u: string) => Promise<any> =
  typeof window !== "undefined"
    ? (new Function("u", "return import(u)") as (u: string) => Promise<any>)
    : async () => ({});

const RFB_URL = "/novnc/core/rfb.js";

export function Console({ serverId }: { serverId: string }) {
  const containerRef = useRef<HTMLDivElement>(null);
  const rfbRef = useRef<any>(null);
  const [phase, setPhase] = useState<Phase>("idle");
  const [message, setMessage] = useState<string | null>(null);

  const cleanup = useCallback(() => {
    if (rfbRef.current) {
      try {
        rfbRef.current.disconnect();
      } catch {
        /* ignore */
      }
      rfbRef.current = null;
    }
  }, []);

  useEffect(() => () => cleanup(), [cleanup]);

  const connect = useCallback(async () => {
    setMessage(null);
    setPhase("loading");
    cleanup();

    // 1. Make sure the vendored noVNC assets are actually present.
    try {
      const head = await fetch(RFB_URL, { method: "HEAD", cache: "no-store" });
      if (!head.ok) throw new Error("assets missing");
    } catch {
      setPhase("unavailable");
      return;
    }

    // 2. Get a fresh single-use console ticket.
    let ticket: { wsPath: string; ticketId: string };
    try {
      const res = await fetch(`/api/console/${serverId}`, { cache: "no-store" });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error || "could not obtain a console ticket");
      }
      ticket = await res.json();
    } catch (err) {
      setPhase("error");
      setMessage(err instanceof Error ? err.message : "could not obtain a console ticket");
      return;
    }

    // 3. Load the vendored RFB client and connect to the relay.
    let RFB: any;
    try {
      const mod = await importESM(RFB_URL);
      RFB = mod.default ?? mod.RFB ?? mod;
      if (typeof RFB !== "function") throw new Error("noVNC RFB module malformed");
    } catch {
      setPhase("unavailable");
      return;
    }

    if (!containerRef.current) return;
    setPhase("connecting");

    try {
      const rfb = new RFB(containerRef.current, ticket.wsPath, {
        wsProtocols: ["binary"],
      });
      rfb.scaleViewport = true;
      rfb.clipViewport = false;
      rfb.resizeSession = false;
      rfb.showDotCursor = true;
      rfb.background = "#05060f";

      rfb.addEventListener("connect", () => setPhase("connected"));
      rfb.addEventListener("disconnect", (e: any) => {
        setPhase("error");
        setMessage(
          e?.detail?.clean
            ? "Console session ended."
            : "Console disconnected — the relay or hypervisor may be unreachable."
        );
        rfbRef.current = null;
      });
      rfb.addEventListener("securityfailure", (e: any) => {
        setPhase("error");
        setMessage(`Console authentication failed${e?.detail?.reason ? `: ${e.detail.reason}` : "."}`);
      });

      rfbRef.current = rfb;
    } catch (err) {
      setPhase("error");
      setMessage(err instanceof Error ? err.message : "failed to start the console");
    }
  }, [serverId, cleanup]);

  const disconnect = useCallback(() => {
    cleanup();
    setPhase("idle");
    setMessage(null);
  }, [cleanup]);

  const sendCtrlAltDel = useCallback(() => {
    try {
      rfbRef.current?.sendCtrlAltDel();
    } catch {
      /* ignore */
    }
  }, []);

  const fullscreen = useCallback(() => {
    const el = containerRef.current?.parentElement;
    if (el?.requestFullscreen) void el.requestFullscreen();
  }, []);

  const active = phase === "connecting" || phase === "connected";

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-semibold">VNC console</h2>
          <p className="mt-1 text-sm text-slate-400">
            Direct graphical access to your server — useful when SSH or networking is unavailable.
          </p>
        </div>
        <div className="flex items-center gap-2">
          {active && (
            <>
              <button type="button" onClick={sendCtrlAltDel} className="btn-secondary">
                Ctrl+Alt+Del
              </button>
              <button type="button" onClick={fullscreen} className="btn-secondary">
                Fullscreen
              </button>
              <button type="button" onClick={disconnect} className="btn-danger">
                Disconnect
              </button>
            </>
          )}
          {!active && phase !== "unavailable" && (
            <button
              type="button"
              onClick={() => void connect()}
              className="btn-primary"
              disabled={phase === "loading"}
            >
              {phase === "loading" ? "Opening…" : "Open console"}
            </button>
          )}
        </div>
      </div>

      {phase === "unavailable" ? (
        <div className="card border-amber-500/30 bg-amber-500/[0.06]">
          <div className="flex items-start gap-3">
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#fbbf24"
              strokeWidth="1.6"
              className="mt-0.5 shrink-0"
            >
              <path d="M12 9v4M12 17h.01" />
              <path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z" />
            </svg>
            <div>
              <h3 className="text-sm font-semibold text-amber-200">Console assets not installed</h3>
              <p className="mt-1 text-sm text-slate-400">
                The noVNC client bundle is missing. An operator can install it by running:
              </p>
              <code className="mt-2 inline-block rounded-lg border border-white/10 bg-navy-950/80 px-2.5 py-1.5 font-mono text-xs">
                scripts/fetch-novnc.sh
              </code>
            </div>
          </div>
        </div>
      ) : (
        <div className="relative overflow-hidden rounded-2xl border border-white/[0.08] bg-[#05060f]">
          <div
            ref={containerRef}
            className="flex min-h-[420px] w-full items-center justify-center"
          >
            {phase === "idle" && (
              <div className="px-6 py-16 text-center">
                <div className="mx-auto mb-4 w-fit rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/15 to-brand-500/15 p-4">
                  <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.5">
                    <rect x="2" y="4" width="20" height="14" rx="2" />
                    <path d="M8 21h8M12 18v3" />
                    <path d="m7 9 3 2-3 2M13 13h4" />
                  </svg>
                </div>
                <p className="text-sm text-slate-400">
                  The console opens a live graphical session. Click{" "}
                  <span className="font-medium text-slate-200">Open console</span> to connect.
                </p>
              </div>
            )}
            {(phase === "loading" || phase === "connecting") && (
              <div className="flex flex-col items-center gap-3 py-16 text-sm text-slate-400">
                <span className="h-6 w-6 animate-spin rounded-full border-2 border-white/20 border-t-brand-400" />
                {phase === "loading" ? "Requesting a secure ticket…" : "Connecting to the console…"}
              </div>
            )}
            {phase === "error" && (
              <div className="px-6 py-16 text-center">
                <p className="text-sm text-red-300">{message ?? "The console is unavailable."}</p>
                <button type="button" onClick={() => void connect()} className="btn-secondary mt-4">
                  Try again
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      <p className="text-xs text-slate-500">
        Console sessions are authenticated with a single-use ticket that expires in 60 seconds. Your
        keystrokes travel to the server over an encrypted relay — credentials are never exposed to your
        browser.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Console } from "@/components/customer/Console";

/**
 * Admin-facing VNC console section for the server detail page.
 *
 * Collapsed by default (the console requests a live Proxmox VNC ticket only
 * when opened). Reuses the same secure Console client — the ticket route
 * authorises admins as well as owners, and credentials stay server-side.
 */
export function ServerConsole({ serverId }: { serverId: string }) {
  const [open, setOpen] = useState(false);

  return (
    <div className="card">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-semibold">Console</h2>
          <p className="mt-1 text-sm text-slate-400">
            Open a graphical VNC session to this VM for hands-on recovery or diagnostics.
          </p>
        </div>
        <button type="button" className="btn-secondary" onClick={() => setOpen((v) => !v)}>
          {open ? "Hide console" : "Show console"}
        </button>
      </div>
      {open && (
        <div className="mt-5 border-t border-white/[0.06] pt-5">
          <Console serverId={serverId} />
        </div>
      )}
    </div>
  );
}

