import https from "node:https";
import http from "node:http";
import net from "node:net";
import fs from "node:fs";
import { createHash, randomBytes } from "node:crypto";
import { EncryptJWT } from "jose";

const AUTH_SECRET = "testsecret";
const KEY = new Uint8Array(createHash("sha256").update(`nxeon-console:${AUTH_SECRET}`).digest());
const GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";

// ---- tiny WS frame helpers (test side) ----
function encode(opcode, payload, mask) {
  const len = payload.length;
  let header;
  if (len < 126) { header = Buffer.alloc(2); header[1] = len; }
  else if (len < 65536) { header = Buffer.alloc(4); header[1] = 126; header.writeUInt16BE(len, 2); }
  else { header = Buffer.alloc(10); header[1] = 127; header.writeBigUInt64BE(BigInt(len), 2); }
  header[0] = 0x80 | opcode;
  if (mask) {
    header[1] |= 0x80;
    const m = randomBytes(4);
    const out = Buffer.allocUnsafe(len);
    for (let i = 0; i < len; i++) out[i] = payload[i] ^ m[i & 3];
    return Buffer.concat([header, m, out]);
  }
  return Buffer.concat([header, payload]);
}
function makeDecoder(onMsg) {
  let buf = Buffer.alloc(0);
  return (chunk) => {
    buf = Buffer.concat([buf, chunk]);
    for (;;) {
      if (buf.length < 2) return;
      const b0 = buf[0], b1 = buf[1];
      const opcode = b0 & 0x0f;
      const masked = (b1 & 0x80) !== 0;
      let len = b1 & 0x7f; let off = 2;
      if (len === 126) { if (buf.length < 4) return; len = buf.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (buf.length < 10) return; len = Number(buf.readBigUInt64BE(2)); off = 10; }
      let mk;
      if (masked) { if (buf.length < off + 4) return; mk = buf.subarray(off, off + 4); off += 4; }
      if (buf.length < off + len) return;
      let p = Buffer.from(buf.subarray(off, off + len));
